-- Port of Administration's InitialSchema migration. Both foreign keys stay
-- inside the schema; nothing outside it references these tables by key
-- (Orders keeps Invoice.CustomerId and Catalog keeps Track.GenreId and
-- Track.MediaTypeId as plain ids, ADR-0004, ADR-0006, ADR-0007).

CREATE TABLE administration."Employee" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "LastName" varchar(20) NULL,
    "FirstName" varchar(20) NULL,
    "Title" varchar(30) NULL,
    "ReportsTo" integer NULL,
    "BirthDate" timestamp with time zone NULL,
    "HireDate" timestamp with time zone NULL,
    "Address" varchar(70) NULL,
    "City" varchar(40) NULL,
    "State" varchar(40) NULL,
    "Country" varchar(40) NULL,
    "PostalCode" varchar(10) NULL,
    "Phone" varchar(24) NULL,
    "Fax" varchar(24) NULL,
    "Email" varchar(60) NULL,
    CONSTRAINT "PK_Employee" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Employee_Employee_ReportsTo" FOREIGN KEY ("ReportsTo") REFERENCES administration."Employee" ("Id")
);

CREATE TABLE administration."Genre" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" varchar(120) NULL,
    CONSTRAINT "PK_Genre" PRIMARY KEY ("Id")
);

CREATE TABLE administration."MediaType" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" varchar(120) NULL,
    CONSTRAINT "PK_MediaType" PRIMARY KEY ("Id")
);

CREATE TABLE administration."Customer" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FirstName" varchar(40) NULL,
    "LastName" varchar(20) NULL,
    "Company" varchar(80) NULL,
    "Address" varchar(70) NULL,
    "City" varchar(40) NULL,
    "State" varchar(40) NULL,
    "Country" varchar(40) NULL,
    "PostalCode" varchar(10) NULL,
    "Phone" varchar(24) NULL,
    "Fax" varchar(24) NULL,
    "Email" varchar(60) NULL,
    "SupportRepId" integer NULL,
    CONSTRAINT "PK_Customer" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Customer_Employee_SupportRepId" FOREIGN KEY ("SupportRepId") REFERENCES administration."Employee" ("Id")
);

CREATE INDEX "IX_Customer_SupportRepId" ON administration."Customer" ("SupportRepId");
CREATE INDEX "IX_Employee_ReportsTo" ON administration."Employee" ("ReportsTo");
